import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

describe('WWW strip regression', () => {
  it('should not strip www when label length is 64 (invalid)', () => {
    const label = 'a'.repeat(64);
    const url = `http://www.${label}.com`;
    const opts = { stripWWW: true };
    const result = normalizeUrl(url, opts);
    assert.ok(result.includes(`www.${label}.com`), `Expected www to remain, got ${result}`);
  });
});"}]}
